function findTheWinner(n, k) {
  // Play the game on an explicit list and delete each loser.
  const circle = [];
  for (let friend = 1; friend <= n; friend++) circle.push(friend);
  let at = 0;
  while (circle.length > 1) {
    at = (at + k - 1) % circle.length;
    circle.splice(at, 1);
    if (at === circle.length) at = 0;
  }
  return circle[0];
}

