function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(450, 500) : int(1, 12);
  const k = rand() < 0.2 ? (rand() < 0.5 ? 1 : n) : int(1, n);
  return [n, k];
}
